fn contains_consecutive_numbers(a: &Vec<i32>) -> bool {
    if a.len() < 2 {
        return false;
    }

    for i in 0..(a.len() - 1) {
        if let Some(next) = a[i].checked_add(1) {
            if next == a[i + 1] {
                return true;
            }
        }
    }

    false
}

